package com.example.customerservice.dto.response;
import java.time.LocalDateTime;
public class CustomerResponse { private Long customerId; private String name; private String email; private String phone; private String address; private Long userId; private LocalDateTime createdAt; public Long getCustomerId(){return customerId;} public void setCustomerId(Long v){this.customerId=v;} public String getName(){return name;} public void setName(String v){this.name=v;} public String getEmail(){return email;} public void setEmail(String v){this.email=v;} public String getPhone(){return phone;} public void setPhone(String v){this.phone=v;} public String getAddress(){return address;} public void setAddress(String v){this.address=v;} public Long getUserId(){return userId;} public void setUserId(Long v){this.userId=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){this.createdAt=v;} }